const data = $input.item.json.output;
if (!data) { return { json: { pageContent: "No data extracted", metadata: {} } }; }
const typeLabel = $input.first().json.output.transaction_type === 'income' ? 'รายรับ' : 'รายจ่าย';
const contentString = `ข้อมูลใบเสร็จ (${typeLabel}):
ผู้ชำระเงิน: ${$input.first().json.output.payer_name || '-'}
ผู้รับเงิน: ${$input.first().json.output.Recipient_name || '-'}
วันที่: ${$input.first().json.output.invoice_date || '-'}
ยอดรวมสุทธิ: ${$input.first().json.output.total_amount || '-'} บาท
กิจกรรม: ${$input.first().json.output.activity || '-'} `;
  return { json: { pageContent: contentString, metadata: { source: "receipt_analysis", timestamp: new Date().toISOString() } } };

const event = $json.body.events[0];
const source = event.source || {};
return {
  json: {
    lineUserId: source.userId || null,
    groupId: source.groupId || null,
    roomId: source.roomId || null,
    chatType: source.type || 'user'
  }
};

const SECRET = "2569xyz"; // ตั้งเองแล้วใช้ค่าเดียวกันทั้ง 2 จุด

function makeToken(id, secret) {
  const s = id + secret;
  let hash = 5381;
  for (let i = 0; i < s.length; i++) {
    hash = ((hash << 5) + hash + s.charCodeAt(i)) | 0;
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

const userId = $('LINE Webhook5').item.json.body.events[0].source.userId;
const token = makeToken(userId, SECRET);
const link = `https://regainable-laurinda-unpromising.ngrok-free.dev/webhook-test/expense-dashboard?token=${token}`;

return {
  json: {
    replyText: `นี่คือลิงก์ dashboard ส่วนตัวของคุณ (เห็นข้อมูลของคุณเท่านั้น):\n${link}`
  }
};

const SECRET = "2569xyz"; // ต้องเหมือนด้านบนเป๊ะ

function makeToken(id, secret) {
  const s = id + secret;
  let hash = 5381;
  for (let i = 0; i < s.length; i++) {
    hash = ((hash << 5) + hash + s.charCodeAt(i)) | 0;
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

const query = $('Dashboard Webhook3').item.json.query || {};
const token = query.token;

let rows = $input.all().map(i => i.json).filter(r => r && r.month);

if (!token) {
  return { json: { html: '<h2>ไม่พบ token กรุณาพิมพ์ "dashboard" คุยกับบอทเพื่อขอลิงก์ใหม่</h2>' } };
}

rows = rows.filter(r => makeToken(r.line_user_id, SECRET) === token);

// เรียงเดือนล่าสุดไว้บนสุดใน Dropdown
rows.sort((a, b) => String(b.month).localeCompare(String(a.month)));

if (rows.length === 0) {
  return { json: { html: '<h2>ไม่มีข้อมูล</h2>' } };
}

const displayName = rows[0].display_name || rows[0].line_user_id;

const optionsHtml = rows.map((r, i) =>
  `<option value="${i}">${r.month}</option>`
).join('');

const monthlyDataJs = rows.map(r => ({
  month: r.month,
  income: Number(r.income || 0),
  expense: Number(r.expense || 0),
  net: Number(r.net || 0)
}));

const html = `<!DOCTYPE html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>สรุปรายรับ-รายจ่ายรายเดือน</title>
<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script>
<style>
body{font-family:sans-serif;padding:24px;background:#f7f7f8}
.card{background:#fff;border-radius:8px;padding:20px;max-width:640px;margin:0 auto 16px;box-shadow:0 1px 4px rgba(0,0,0,0.1)}
h2{margin-top:0}
select{width:100%;padding:10px;font-size:16px;border-radius:6px;border:1px solid #ddd;margin-bottom:16px}
.summary-row{display:flex;justify-content:space-between;margin-bottom:6px;font-size:15px}
.income{color:#0a7d2c;font-weight:bold}
.expense{color:#c0392b;font-weight:bold}
.net{font-weight:bold}
</style></head><body>

<div class="card">
  <h2>สรุปรายรับ-รายจ่ายรายเดือน (ส่วนตัว)</h2>
  <div style="color:#666;margin-bottom:12px">ผู้ใช้: ${displayName}</div>
  <select id="monthSelect">${optionsHtml}</select>
  <div class="summary-row"><span>รายรับ</span><span class="income" id="incomeVal"></span></div>
  <div class="summary-row"><span>รายจ่าย</span><span class="expense" id="expenseVal"></span></div>
  <div class="summary-row"><span>คงเหลือสุทธิ</span><span class="net" id="netVal"></span></div>
  <canvas id="summaryChart" height="180"></canvas>
</div>

<script>
const monthlyData = ${JSON.stringify(monthlyDataJs)};
let chart;

function render(idx) {
  const d = monthlyData[idx];
  document.getElementById('incomeVal').textContent = d.income.toLocaleString('th-TH', {minimumFractionDigits:2}) + ' บาท';
  document.getElementById('expenseVal').textContent = d.expense.toLocaleString('th-TH', {minimumFractionDigits:2}) + ' บาท';
  document.getElementById('netVal').textContent = d.net.toLocaleString('th-TH', {minimumFractionDigits:2}) + ' บาท';

  if (chart) chart.destroy();
  chart = new Chart(document.getElementById('summaryChart'), {
    type: 'bar',
    data: {
      labels: ['รายรับ', 'รายจ่าย'],
      datasets: [{ data: [d.income, d.expense], backgroundColor: ['#0a7d2c', '#c0392b'] }]
    },
    options: { plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } }
  });
}

document.getElementById('monthSelect').addEventListener('change', (e) => render(e.target.value));
render(0);
</script>
</body></html>`;

return { json: { html } };
